import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.Ke88N3OB.js";var c=JSON.parse(`{"title":"Waypoints","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/waypoints/README.md"},"headers":[],"relativePath":"packages/waypoints/README.md","filePath":"packages/waypoints/README.md","lastUpdated":1792508673000}`),l={name:`packages/waypoints/README.md`},u={id:`waypoints`,tabindex:`-1`,class:`component-page-title`},d={class:`component-page-title__version`,href:`https://github.com/filiphsps/pumpkin-plugins/releases/tag/waypoints-v0.1.0`,"aria-label":`Release v0.1.0`};function f(i,c,l,f,p,m){let h=s(`Badge`);return e(),o(`div`,null,[n(`h1`,u,[c[0]||=n(`span`,{class:`component-page-title__text`},[t(`Waypoints `),n(`a`,{class:`header-anchor`,href:`#waypoints`,"aria-label":`Permalink to “Waypoints”`},`​`)],-1),n(`a`,d,[a(h,{type:`info`,text:`v0.1.0`})])]),c[1]||=r(`<p>Waypoints lets you create shared locations, control who can access each one, show them on a Java HUD, and look them up with PumpkinPIE placeholders.</p><p>See the <a href="https://filiphsps.github.io/pumpkin-plugins/packages/waypoints/docs/" target="_blank" rel="noreferrer">plugin guide</a> and <a href="https://filiphsps.github.io/pumpkin-plugins/api/plugins/waypoints/" target="_blank" rel="noreferrer">API reference</a> on the documentation site.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>Waypoints stores shared named locations on the server. Each waypoint can have a display label, description, color, item icon, and optional HUD visibility range. Waypoints are restricted by default; operators can make them public or grant access to specific players, permission nodes, or permission-marker groups. Players can find and teleport to enabled waypoints they can access. Records have no creator ownership.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to “Installation”">​</a></h2><p>Download <code>waypoints.wasm</code> from the plugin&#39;s GitHub release, put it in your server&#39;s <code>plugins/</code> folder, and restart Pumpkin. On the first load, a full restart lets Pumpkin ask for the plugin&#39;s permissions; hot reload cannot prompt for them.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to “Permissions”">​</a></h2><p>Pumpkin asks you to approve these on the server console when it loads the plugin. It skips the question when the <code>[plugins]</code> table in <code>pumpkin.toml</code> lists all of them in <code>allowed_permissions</code> or sets <code>ask_permission_confirmation = false</code>. Pumpkin remembers your answer and asks again after the plugin file or this list changes.</p><table tabindex="0"><thead><tr><th>Permission</th><th>Why</th></tr></thead><tbody><tr><td><code>fs.read.data</code></td><td>Read the waypoint store from the plugin data folder.</td></tr><tr><td><code>fs.write.data</code></td><td>Persist waypoint changes in the plugin data folder.</td></tr><tr><td><code>http.outbound</code></td><td>Check Pumpkin Market for plugin updates.</td></tr></tbody></table><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to “Commands”">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th><th>Permission</th><th>Default access</th></tr></thead><tbody><tr><td><code>/wp create</code></td><td>Create a waypoint at your position or explicit coordinates</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp create &lt;name&gt;</code></td><td>Create a waypoint at your position or explicit coordinates</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp create &lt;name&gt; &lt;x&gt; &lt;y&gt; &lt;z&gt;</code></td><td>Create a waypoint at your position or explicit coordinates</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp reload</code></td><td>Reload waypoint data from disk</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp delete &lt;name&gt;</code></td><td>Delete a waypoint by name</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp rename &lt;name&gt; &lt;newName&gt;</code></td><td>Rename a waypoint</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp relocate</code></td><td>Move a waypoint to your position or explicit coordinates</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp relocate &lt;name&gt;</code></td><td>Move a waypoint to your position or explicit coordinates</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp relocate &lt;name&gt; &lt;x&gt; &lt;y&gt; &lt;z&gt;</code></td><td>Move a waypoint to your position or explicit coordinates</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp list</code></td><td>List enabled waypoints you can access</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp info &lt;name&gt;</code></td><td>Show details for an enabled waypoint you can access</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp teleport</code></td><td>Teleport to a waypoint or, as an operator, teleport selected players</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp teleport &lt;name&gt;</code></td><td>Teleport to a waypoint or, as an operator, teleport selected players</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp teleport &lt;name&gt; &lt;targets&gt;</code></td><td>Teleport to a waypoint or, as an operator, teleport selected players</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp tp</code></td><td>Alias for teleport</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp tp &lt;name&gt;</code></td><td>Alias for teleport</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp tp &lt;name&gt; &lt;targets&gt;</code></td><td>Alias for teleport</td><td><code>Waypoints:command.use</code></td><td>everyone</td></tr><tr><td><code>/wp enable &lt;name&gt;</code></td><td>Enable a waypoint</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp disable &lt;name&gt;</code></td><td>Disable a waypoint</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp get &lt;name&gt;</code></td><td>Inspect a waypoint, including disabled records</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp access public &lt;name&gt;</code></td><td>Allow every player to access a waypoint</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp access restricted &lt;name&gt;</code></td><td>Restrict a waypoint to its grants</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp access list &lt;name&gt;</code></td><td>List a waypoint access mode and its grants</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp access grant player &lt;name&gt; &lt;player&gt;</code></td><td>Grant access to an online player</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp access grant permission &lt;name&gt; &lt;permission&gt;</code></td><td>Grant access to a permission node</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp access grant group &lt;name&gt; &lt;group&gt;</code></td><td>Grant access to a permission marker group</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp access revoke player &lt;name&gt; &lt;player&gt;</code></td><td>Revoke an online player grant</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp access revoke permission &lt;name&gt; &lt;permission&gt;</code></td><td>Revoke a permission node grant</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp access revoke group &lt;name&gt; &lt;group&gt;</code></td><td>Revoke a permission marker group grant</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp set color &lt;name&gt; &lt;hex&gt;</code></td><td>Set the waypoint color</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp set icon &lt;name&gt; &lt;item&gt;</code></td><td>Set the waypoint item icon</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp set label &lt;name&gt; &lt;label&gt;</code></td><td>Set the waypoint display label</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp set description &lt;name&gt; &lt;description&gt;</code></td><td>Set the waypoint description</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp set visibility-range &lt;name&gt; &lt;range&gt;</code></td><td>Set the waypoint rendering range in blocks</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr><tr><td><code>/wp reset &lt;property&gt; &lt;name&gt;</code></td><td>Reset one mutable waypoint property to its default</td><td><code>Waypoints:command.admin</code></td><td>operators (level 3)</td></tr></tbody></table><h2 id="pumpkinpie-placeholders" tabindex="-1">PumpkinPIE placeholders <a class="header-anchor" href="#pumpkinpie-placeholders" aria-label="Permalink to “PumpkinPIE placeholders”">​</a></h2><table tabindex="0"><thead><tr><th>Token</th><th>Description</th></tr></thead><tbody><tr><td><code>%waypoints_count%</code></td><td>Accessible enabled waypoint count across all worlds.</td></tr><tr><td><code>%waypoints_count_here%</code></td><td>Accessible enabled waypoint count in the current world.</td></tr><tr><td><code>%waypoints_count_world:world%</code></td><td>Accessible enabled waypoint count in the exact argument world.</td></tr><tr><td><code>%waypoints_public_count%</code></td><td>Accessible public-record count across all worlds.</td></tr><tr><td><code>%waypoints_restricted_count%</code></td><td>Accessible restricted-record count across all worlds.</td></tr><tr><td><code>%waypoints_visible_count%</code></td><td>Same-world count eligible for the HUD visibility range.</td></tr><tr><td><code>%waypoints_nearby_count:128%</code></td><td>Same-world count within the 3D radius in blocks.</td></tr><tr><td><code>%waypoints_names%</code></td><td>Accessible waypoint names across worlds, joined by comma and space.</td></tr><tr><td><code>%waypoints_names_here%</code></td><td>Accessible same-world waypoint names, joined by comma and space.</td></tr><tr><td><code>%waypoints_closest_exists%</code></td><td>Whether an accessible same-world closest waypoint exists.</td></tr><tr><td><code>%waypoints_nearest_exists:2%</code></td><td>Whether the requested accessible same-world rank exists.</td></tr><tr><td><code>%waypoints_waypoint_exists:11111111-1111-4111-8111-111111111111%</code></td><td>Whether the enabled UUID is accessible to the viewer.</td></tr><tr><td><code>%waypoints_closest_id%</code></td><td>Canonical waypoint UUID (closest accessible same-world waypoint).</td></tr><tr><td><code>%waypoints_nearest_id:2%</code></td><td>Canonical waypoint UUID (requested accessible same-world rank).</td></tr><tr><td><code>%waypoints_waypoint_id:11111111-1111-4111-8111-111111111111%</code></td><td>Canonical waypoint UUID (accessible waypoint UUID argument).</td></tr><tr><td><code>%waypoints_closest_name%</code></td><td>Complete saved waypoint name (closest accessible same-world waypoint).</td></tr><tr><td><code>%waypoints_nearest_name:2%</code></td><td>Complete saved waypoint name (requested accessible same-world rank).</td></tr><tr><td><code>%waypoints_waypoint_name:11111111-1111-4111-8111-111111111111%</code></td><td>Complete saved waypoint name (accessible waypoint UUID argument).</td></tr><tr><td><code>%waypoints_closest_label%</code></td><td>Saved display label, falling back to the name (closest accessible same-world waypoint).</td></tr><tr><td><code>%waypoints_nearest_label:2%</code></td><td>Saved display label, falling back to the name (requested accessible same-world rank).</td></tr><tr><td><code>%waypoints_waypoint_label:11111111-1111-4111-8111-111111111111%</code></td><td>Saved display label, falling back to the name (accessible waypoint UUID argument).</td></tr><tr><td><code>%waypoints_closest_description%</code></td><td>Saved description, or an empty string (closest accessible same-world waypoint).</td></tr><tr><td><code>%waypoints_nearest_description:2%</code></td><td>Saved description, or an empty string (requested accessible same-world rank).</td></tr><tr><td><code>%waypoints_waypoint_description:11111111-1111-4111-8111-111111111111%</code></td><td>Saved description, or an empty string (accessible waypoint UUID argument).</td></tr><tr><td><code>%waypoints_closest_world%</code></td><td>Exact saved world key (closest accessible same-world waypoint).</td></tr><tr><td><code>%waypoints_nearest_world:2%</code></td><td>Exact saved world key (requested accessible same-world rank).</td></tr><tr><td><code>%waypoints_waypoint_world:11111111-1111-4111-8111-111111111111%</code></td><td>Exact saved world key (accessible waypoint UUID argument).</td></tr><tr><td><code>%waypoints_closest_color%</code></td><td>Canonical waypoint color (closest accessible same-world waypoint).</td></tr><tr><td><code>%waypoints_nearest_color:2%</code></td><td>Canonical waypoint color (requested accessible same-world rank).</td></tr><tr><td><code>%waypoints_waypoint_color:11111111-1111-4111-8111-111111111111%</code></td><td>Canonical waypoint color (accessible waypoint UUID argument).</td></tr><tr><td><code>%waypoints_closest_icon%</code></td><td>Canonical item ID, or an empty string (closest accessible same-world waypoint).</td></tr><tr><td><code>%waypoints_nearest_icon:2%</code></td><td>Canonical item ID, or an empty string (requested accessible same-world rank).</td></tr><tr><td><code>%waypoints_waypoint_icon:11111111-1111-4111-8111-111111111111%</code></td><td>Canonical item ID, or an empty string (accessible waypoint UUID argument).</td></tr><tr><td><code>%waypoints_closest_x%</code></td><td>Saved X coordinate (closest accessible same-world waypoint).</td></tr><tr><td><code>%waypoints_nearest_x:2%</code></td><td>Saved X coordinate (requested accessible same-world rank).</td></tr><tr><td><code>%waypoints_waypoint_x:11111111-1111-4111-8111-111111111111%</code></td><td>Saved X coordinate (accessible waypoint UUID argument).</td></tr><tr><td><code>%waypoints_closest_y%</code></td><td>Saved Y coordinate (closest accessible same-world waypoint).</td></tr><tr><td><code>%waypoints_nearest_y:2%</code></td><td>Saved Y coordinate (requested accessible same-world rank).</td></tr><tr><td><code>%waypoints_waypoint_y:11111111-1111-4111-8111-111111111111%</code></td><td>Saved Y coordinate (accessible waypoint UUID argument).</td></tr><tr><td><code>%waypoints_closest_z%</code></td><td>Saved Z coordinate (closest accessible same-world waypoint).</td></tr><tr><td><code>%waypoints_nearest_z:2%</code></td><td>Saved Z coordinate (requested accessible same-world rank).</td></tr><tr><td><code>%waypoints_waypoint_z:11111111-1111-4111-8111-111111111111%</code></td><td>Saved Z coordinate (accessible waypoint UUID argument).</td></tr><tr><td><code>%waypoints_closest_distance%</code></td><td>Raw three-dimensional distance (closest accessible same-world waypoint).</td></tr><tr><td><code>%waypoints_nearest_distance:2%</code></td><td>Raw three-dimensional distance (requested accessible same-world rank).</td></tr><tr><td><code>%waypoints_waypoint_distance:11111111-1111-4111-8111-111111111111%</code></td><td>Raw three-dimensional distance (accessible waypoint UUID argument).</td></tr><tr><td><code>%waypoints_closest_distance_horizontal%</code></td><td>Raw X/Z distance (closest accessible same-world waypoint).</td></tr><tr><td><code>%waypoints_nearest_distance_horizontal:2%</code></td><td>Raw X/Z distance (requested accessible same-world rank).</td></tr><tr><td><code>%waypoints_waypoint_distance_horizontal:11111111-1111-4111-8111-111111111111%</code></td><td>Raw X/Z distance (accessible waypoint UUID argument).</td></tr><tr><td><code>%waypoints_closest_distance_formatted%</code></td><td>Human-readable distance (closest accessible same-world waypoint).</td></tr><tr><td><code>%waypoints_nearest_distance_formatted:2%</code></td><td>Human-readable distance (requested accessible same-world rank).</td></tr><tr><td><code>%waypoints_waypoint_distance_formatted:11111111-1111-4111-8111-111111111111%</code></td><td>Human-readable distance (accessible waypoint UUID argument).</td></tr><tr><td><code>%waypoints_closest_delta_x%</code></td><td>Destination X minus viewer X (closest accessible same-world waypoint).</td></tr><tr><td><code>%waypoints_nearest_delta_x:2%</code></td><td>Destination X minus viewer X (requested accessible same-world rank).</td></tr><tr><td><code>%waypoints_waypoint_delta_x:11111111-1111-4111-8111-111111111111%</code></td><td>Destination X minus viewer X (accessible waypoint UUID argument).</td></tr><tr><td><code>%waypoints_closest_delta_y%</code></td><td>Destination Y minus viewer Y (closest accessible same-world waypoint).</td></tr><tr><td><code>%waypoints_nearest_delta_y:2%</code></td><td>Destination Y minus viewer Y (requested accessible same-world rank).</td></tr><tr><td><code>%waypoints_waypoint_delta_y:11111111-1111-4111-8111-111111111111%</code></td><td>Destination Y minus viewer Y (accessible waypoint UUID argument).</td></tr><tr><td><code>%waypoints_closest_delta_z%</code></td><td>Destination Z minus viewer Z (closest accessible same-world waypoint).</td></tr><tr><td><code>%waypoints_nearest_delta_z:2%</code></td><td>Destination Z minus viewer Z (requested accessible same-world rank).</td></tr><tr><td><code>%waypoints_waypoint_delta_z:11111111-1111-4111-8111-111111111111%</code></td><td>Destination Z minus viewer Z (accessible waypoint UUID argument).</td></tr><tr><td><code>%waypoints_closest_bearing%</code></td><td>Horizontal compass bearing, north at zero (closest accessible same-world waypoint).</td></tr><tr><td><code>%waypoints_nearest_bearing:2%</code></td><td>Horizontal compass bearing, north at zero (requested accessible same-world rank).</td></tr><tr><td><code>%waypoints_waypoint_bearing:11111111-1111-4111-8111-111111111111%</code></td><td>Horizontal compass bearing, north at zero (accessible waypoint UUID argument).</td></tr><tr><td><code>%waypoints_closest_direction%</code></td><td>Eight-point compass direction (closest accessible same-world waypoint).</td></tr><tr><td><code>%waypoints_nearest_direction:2%</code></td><td>Eight-point compass direction (requested accessible same-world rank).</td></tr><tr><td><code>%waypoints_waypoint_direction:11111111-1111-4111-8111-111111111111%</code></td><td>Eight-point compass direction (accessible waypoint UUID argument).</td></tr><tr><td><code>%waypoints_closest_relative_direction%</code></td><td>Eight-point direction relative to the viewer yaw (closest accessible same-world waypoint).</td></tr><tr><td><code>%waypoints_nearest_relative_direction:2%</code></td><td>Eight-point direction relative to the viewer yaw (requested accessible same-world rank).</td></tr><tr><td><code>%waypoints_waypoint_relative_direction:11111111-1111-4111-8111-111111111111%</code></td><td>Eight-point direction relative to the viewer yaw (accessible waypoint UUID argument).</td></tr></tbody></table><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h2><p>This plugin has no configuration file.</p><h2 id="guide" tabindex="-1">Guide <a class="header-anchor" href="#guide" aria-label="Permalink to “Guide”">​</a></h2><p>See the <a href="./docs/">Waypoints guide</a> for command examples, access rules, storage behavior, and Java HUD details. See the <a href="./docs/placeholders">PumpkinPIE placeholder guide</a> for the optional live lookup contract.</p>`,17)])}var p=i(l,[[`render`,f]]);export{c as __pageData,p as default};